export default function ContactForm() {
  async function submitContact(formData: FormData) {
    'use server';

    const name = formData.get('name');
    const email = formData.get('email');
    const message = formData.get('message');

    // JavaScript validation in the server action
    if (!name || !email || !message) {
      throw new Error('All fields (name, email, message) are required.');
    }

    // In a real application, you would save the data here
    console.log('Contact form submitted:', { name, email, message });
  }

  return (
    <div className="p-4 border rounded shadow-md max-w-md mx-auto mt-10">
      <h2 className="text-xl font-bold mb-4">Contact Us</h2>
      <form action={submitContact} className="flex flex-col gap-4">
        <div className="flex flex-col">
          <label htmlFor="name" className="font-medium mb-1">Name</label>
          <input
            type="text"
            name="name"
            id="name"
            placeholder="Your Name"
            className="border p-2 rounded"
            required
          />
        </div>

        <div className="flex flex-col">
          <label htmlFor="email" className="font-medium mb-1">Email</label>
          <input
            type="email"
            name="email"
            id="email"
            placeholder="your@email.com"
            className="border p-2 rounded"
            required
          />
        </div>

        <div className="flex flex-col">
          <label htmlFor="message" className="font-medium mb-1">Message</label>
          <textarea
            name="message"
            id="message"
            placeholder="Your message..."
            rows={4}
            className="border p-2 rounded"
            required
          ></textarea>
        </div>

        <button
          type="submit"
          className="bg-blue-500 text-white p-2 rounded hover:bg-blue-600 transition-colors"
        >
          Send Message
        </button>
      </form>
    </div>
  );
}

